//! pulp_ostree — OSTree commit/ref/object content plugin.
//!
//! Mirrors `pulp_ostree`:
//! - Object path classifier: `objects/<aa>/<rest>.<kind>` where `<kind>` is
//!   `commit | dirtree | dirmeta | filez | file | tombstone-commit`.
//! - Ref parser: `refs/heads/<branch>` and `refs/remotes/<remote>/<branch>`.
//! - Top-level `summary` and `config` recognition.
//! - Per-publication `refs` listing + `summary` JSON manifest (the
//!   binary GVariant `summary` is generated by the publication layer;
//!   the plugin emits the structured input for it).

use crate::pulp::error::ArtifactsError;
use crate::pulp::models::{ContentUnit, PluginType, RepositoryVersion};
use crate::pulp::plugin::ArtifactsPlugin;
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

pub struct OstreePlugin;

/// Recognised OSTree object kind (the suffix on `objects/<aa>/<rest>.<kind>`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OstreeObjectKind {
    Commit,
    DirTree,
    DirMeta,
    Filez,
    File,
    TombstoneCommit,
}

impl OstreeObjectKind {
    pub fn from_extension(ext: &str) -> Option<Self> {
        match ext {
            "commit" => Some(Self::Commit),
            "dirtree" => Some(Self::DirTree),
            "dirmeta" => Some(Self::DirMeta),
            "filez" => Some(Self::Filez),
            "file" => Some(Self::File),
            "tombstone-commit" => Some(Self::TombstoneCommit),
            _ => None,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Commit => "commit",
            Self::DirTree => "dirtree",
            Self::DirMeta => "dirmeta",
            Self::Filez => "filez",
            Self::File => "file",
            Self::TombstoneCommit => "tombstone-commit",
        }
    }
}

/// Classification of a path inside an OSTree repository.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OstreePath {
    /// `objects/<aa>/<rest>.<kind>` — full 64-hex checksum is `<aa><rest>`.
    Object { checksum: String, kind: OstreeObjectKind },
    /// `refs/heads/<branch>` or `refs/remotes/<remote>/<branch>`.
    Ref { name: String, remote: Option<String> },
    /// Top-level `summary` GVariant.
    Summary,
    /// Top-level `config` ini.
    Config,
    /// Anything else (deltas, signatures, …) — kept verbatim.
    Other,
}

pub fn classify_path(relative_path: &str) -> OstreePath {
    if let Some(rest) = relative_path.strip_prefix("objects/") {
        if let Some((hex_dir, file)) = rest.split_once('/') {
            if let Some((rest_hex, ext)) = file.rsplit_once('.') {
                if hex_dir.len() == 2
                    && hex_dir.chars().all(|c| c.is_ascii_hexdigit())
                    && rest_hex.chars().all(|c| c.is_ascii_hexdigit())
                {
                    let checksum = format!("{hex_dir}{rest_hex}");
                    if let Some(kind) = OstreeObjectKind::from_extension(ext) {
                        return OstreePath::Object { checksum, kind };
                    }
                }
            }
        }
    }
    if let Some(rest) = relative_path.strip_prefix("refs/") {
        if let Some(branch) = rest.strip_prefix("heads/") {
            return OstreePath::Ref { name: branch.to_string(), remote: None };
        }
        if let Some(after) = rest.strip_prefix("remotes/") {
            if let Some((remote, branch)) = after.split_once('/') {
                return OstreePath::Ref {
                    name: branch.to_string(),
                    remote: Some(remote.to_string()),
                };
            }
        }
    }
    match relative_path {
        "summary" => OstreePath::Summary,
        "config" => OstreePath::Config,
        _ => OstreePath::Other,
    }
}

impl ArtifactsPlugin for OstreePlugin {
    fn plugin_type(&self) -> PluginType {
        PluginType::OSTree
    }

    fn name(&self) -> &str {
        "pulp_ostree"
    }

    fn content_types(&self) -> Vec<&str> {
        vec![
            "ostree.commit",
            "ostree.ref",
            "ostree.object",
            "ostree.config",
            "ostree.summary",
        ]
    }

    fn parse_content(
        &self,
        data: &[u8],
        relative_path: &str,
    ) -> Result<ContentUnit, ArtifactsError> {
        let sha256 = hex::encode(Sha256::digest(data));
        let path = classify_path(relative_path);
        let (content_type, mut meta) = match &path {
            OstreePath::Object { checksum, kind } => (
                "object",
                serde_json::json!({
                    "checksum": checksum,
                    "object_kind": kind.as_str(),
                }),
            ),
            OstreePath::Ref { name, remote } => (
                "ref",
                serde_json::json!({
                    "ref_name": name,
                    "remote": remote,
                    "checksum": String::from_utf8_lossy(data).trim().to_string(),
                }),
            ),
            OstreePath::Summary => ("summary", serde_json::json!({})),
            OstreePath::Config => ("config", serde_json::json!({})),
            OstreePath::Other => ("other", serde_json::json!({})),
        };
        meta["content_type"] = serde_json::json!(content_type);
        meta["relative_path"] = serde_json::json!(relative_path);

        let mut unit = ContentUnit::new(PluginType::OSTree, meta);
        unit.relative_path = Some(relative_path.to_string());
        unit.sha256 = Some(sha256);
        unit.size = Some(data.len() as u64);
        Ok(unit)
    }

    fn generate_metadata(
        &self,
        _repo_version: &RepositoryVersion,
        units: &[ContentUnit],
    ) -> serde_json::Value {
        let mut refs: BTreeMap<String, String> = BTreeMap::new();
        let mut commit_count = 0usize;
        let mut object_count = 0usize;
        for u in units {
            match u.metadata.get("content_type").and_then(|v| v.as_str()) {
                Some("ref") => {
                    let name = u.metadata["ref_name"].as_str().unwrap_or("").to_string();
                    let checksum = u.metadata["checksum"].as_str().unwrap_or("").to_string();
                    refs.insert(name, checksum);
                }
                Some("object") => {
                    object_count += 1;
                    if u.metadata.get("object_kind").and_then(|v| v.as_str()) == Some("commit") {
                        commit_count += 1;
                    }
                }
                _ => {}
            }
        }

        serde_json::json!({
            "refs": refs,
            "ref_count": refs.len(),
            "summary": {
                "refs": refs.iter().map(|(name, checksum)| serde_json::json!({
                    "name": name,
                    "checksum": checksum,
                })).collect::<Vec<_>>(),
                "metadata": {
                    "ostree.commit-count": commit_count,
                    "ostree.object-count": object_count,
                },
            },
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classify_commit_object() {
        let path = classify_path(
            "objects/ab/cdef0123456789012345678901234567890123456789012345678901234567.commit",
        );
        match path {
            OstreePath::Object { checksum, kind } => {
                assert_eq!(checksum.len(), 64);
                assert!(checksum.starts_with("abcdef"));
                assert_eq!(kind, OstreeObjectKind::Commit);
            }
            other => panic!("expected Object, got {other:?}"),
        }
    }

    #[test]
    fn classify_filez_and_dirtree() {
        for (ext, expected) in [
            ("filez", OstreeObjectKind::Filez),
            ("dirtree", OstreeObjectKind::DirTree),
            ("dirmeta", OstreeObjectKind::DirMeta),
            ("file", OstreeObjectKind::File),
            ("tombstone-commit", OstreeObjectKind::TombstoneCommit),
        ] {
            let path = classify_path(&format!(
                "objects/ab/cdef0123456789012345678901234567890123456789012345678901234567.{ext}",
            ));
            match path {
                OstreePath::Object { kind, .. } => assert_eq!(kind, expected, "ext {ext}"),
                other => panic!("expected Object for ext {ext}, got {other:?}"),
            }
        }
    }

    #[test]
    fn classify_local_ref() {
        match classify_path("refs/heads/fedora/41/x86_64/silverblue") {
            OstreePath::Ref { name, remote } => {
                assert_eq!(name, "fedora/41/x86_64/silverblue");
                assert!(remote.is_none());
            }
            other => panic!("expected local ref, got {other:?}"),
        }
    }

    #[test]
    fn classify_remote_ref() {
        match classify_path("refs/remotes/upstream/fedora/41/x86_64/silverblue") {
            OstreePath::Ref { name, remote } => {
                assert_eq!(name, "fedora/41/x86_64/silverblue");
                assert_eq!(remote.as_deref(), Some("upstream"));
            }
            other => panic!("expected remote ref, got {other:?}"),
        }
    }

    #[test]
    fn classify_summary_and_config() {
        assert_eq!(classify_path("summary"), OstreePath::Summary);
        assert_eq!(classify_path("config"), OstreePath::Config);
    }

    #[test]
    fn classify_falls_through_to_other() {
        match classify_path("deltas/some/path") {
            OstreePath::Other => {}
            other => panic!("expected Other, got {other:?}"),
        }
    }

    #[test]
    fn classify_rejects_non_hex_object_dir() {
        match classify_path(
            "objects/zz/cdef0123456789012345678901234567890123456789012345678901234567.commit",
        ) {
            OstreePath::Other => {}
            other => panic!("expected Other, got {other:?}"),
        }
    }

    #[test]
    fn parse_content_for_object_emits_checksum_and_kind() {
        let plugin = OstreePlugin;
        let path =
            "objects/ab/cdef0123456789012345678901234567890123456789012345678901234567.commit";
        let unit = plugin.parse_content(b"x", path).unwrap();
        assert_eq!(unit.metadata["content_type"], "object");
        assert_eq!(unit.metadata["object_kind"], "commit");
        assert!(unit.metadata["checksum"].as_str().unwrap().starts_with("abcdef"));
    }

    #[test]
    fn parse_content_for_ref_stores_target_checksum() {
        let plugin = OstreePlugin;
        let unit = plugin
            .parse_content(
                b"abcdef0123456789012345678901234567890123456789012345678901234567\n",
                "refs/heads/main",
            )
            .unwrap();
        assert_eq!(unit.metadata["content_type"], "ref");
        assert_eq!(unit.metadata["ref_name"], "main");
        assert_eq!(
            unit.metadata["checksum"].as_str().unwrap(),
            "abcdef0123456789012345678901234567890123456789012345678901234567"
        );
    }

    #[test]
    fn generate_metadata_builds_summary_with_refs() {
        let plugin = OstreePlugin;
        let main_ref = plugin.parse_content(b"aaaa", "refs/heads/main").unwrap();
        let dev_ref = plugin.parse_content(b"bbbb", "refs/heads/dev").unwrap();
        let commit = plugin
            .parse_content(
                b"x",
                "objects/ab/cdef0123456789012345678901234567890123456789012345678901234567.commit",
            )
            .unwrap();
        let dirtree = plugin
            .parse_content(
                b"x",
                "objects/cd/ef0123456789012345678901234567890123456789012345678901234567ab.dirtree",
            )
            .unwrap();
        let ver = RepositoryVersion::new("/pulp/api/v3/repositories/ostree/ostree/x/", 1);
        let meta = plugin.generate_metadata(&ver, &[main_ref, dev_ref, commit, dirtree]);
        assert_eq!(meta["ref_count"], 2);
        let refs = meta["summary"]["refs"].as_array().unwrap();
        assert_eq!(refs.len(), 2);
        assert!(refs.iter().any(|r| r["name"] == "main"));
        assert!(refs.iter().any(|r| r["name"] == "dev"));
        assert_eq!(
            meta["summary"]["metadata"]["ostree.commit-count"].as_u64().unwrap(),
            1
        );
        assert_eq!(
            meta["summary"]["metadata"]["ostree.object-count"].as_u64().unwrap(),
            2
        );
    }

    #[test]
    fn content_types_match_pulp_ostree_models() {
        let plugin = OstreePlugin;
        let kinds = plugin.content_types();
        for required in [
            "ostree.commit",
            "ostree.ref",
            "ostree.object",
            "ostree.config",
            "ostree.summary",
        ] {
            assert!(kinds.contains(&required), "missing kind {required}");
        }
    }
}
